     id: 'atv_palestra',
     titulo: 'Abertura',
     tipo: 'palestra',
     salaId: 'auditorio',
     vagas: 200,
     encontros: [{ id: 'enc_1', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' }],
     cargaHorariaMinutos: 120,
